insert into question_pyq_meta (question_id, appear_count, years, exams, verified)
select id, appear_count, coalesce((select array_agg(v::int) from jsonb_array_elements_text(years) as v), '{}')::int[], coalesce((select array_agg(v) from jsonb_array_elements_text(exams) as v), '{}')::text[], verified
from jsonb_to_recordset($json$[{"id":"che-st-101","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Lavoisier’s law of conservation of mass states that, in a closed chemical change, the total mass of reactants compared with products is","options":["always greater","always smaller","exactly the same","unrelated"],"answer_index":2,"explanation":"Mass is neither created nor destroyed in ordinary chemical reactions, so reactant and product masses match.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"laws-combination","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-102","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Proust’s law of definite proportions says that a given pure compound always contains the same elements combined in","options":["any convenient ratio","a fixed mass ratio","a ratio that depends on how it was prepared","equal numbers of grams only"],"answer_index":1,"explanation":"The elemental composition by mass of a pure compound is constant, independent of source.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"laws-combination","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-103","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Dalton’s law of multiple proportions applies when two elements form more than one compound. The masses of one element that combine with a fixed mass of the other stand in","options":["a simple whole-number ratio","an irrational ratio","the ratio of their densities","a 1:1 mass ratio always"],"answer_index":0,"explanation":"Different compounds of the same two elements show small-integer mass ratios for one element at fixed mass of the other.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"laws-combination","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-104","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Gay-Lussac’s law of combining volumes concerns gases measured at the same temperature and pressure. Their reacting volumes are","options":["in simple whole-number ratios","always equal to one litre","inversely proportional to molar mass only","unrelated to the chemical equation"],"answer_index":0,"explanation":"Gaseous reactants and products combine or form in small integer volume ratios under identical T and P.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"laws-combination","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-105","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Avogadro’s hypothesis, used with Gay-Lussac’s volume data, states that equal volumes of gases at the same T and P contain","options":["equal numbers of molecules","equal masses of gas","equal numbers of atoms in every case","one mole only if the gas is monatomic"],"answer_index":0,"explanation":"Equal gas volumes at the same T and P hold the same number of molecules, which explains simple volume ratios.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"laws-combination","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-106","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The law of reciprocal proportions (Richter) compares how two elements A and B each combine with a fixed mass of a third element C. The A:B mass ratio so obtained is","options":["the same as, or a simple multiple of, the ratio in which A and B combine with each other","always 1:1 by mass","equal to their atomic numbers","independent of any compound of A with B"],"answer_index":0,"explanation":"Masses of A and B that combine with a fixed mass of C match the combining ratio of A with B, or a simple multiple of it.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"laws-combination","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-107","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"In a sealed tube, 12 g of carbon is burnt completely in 32 g of oxygen to give carbon dioxide only. The mass of $\\mathrm{CO_2}$ that must be collected is","options":["12 g","32 g","44 g","16 g"],"answer_index":2,"explanation":"Conservation of mass requires $12 + 32 = 44$ g of product when nothing else is formed.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"laws-combination","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-108","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Carbon forms two oxides. With 12 g of carbon, one oxide contains 16 g of oxygen and the other contains 32 g of oxygen. These oxygen masses illustrate multiple proportions because their ratio is","options":["1 : 2","2 : 3","3 : 4","1 : 1"],"answer_index":0,"explanation":"For a fixed 12 g of carbon the oxygen masses 16 g and 32 g stand in the simple ratio 1 : 2.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"laws-combination","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-109","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"At the same T and P, two volumes of hydrogen gas combine with one volume of oxygen gas to give steam. The volume of steam formed, if measured under the same conditions, is","options":["1 volume","2 volumes","3 volumes","4 volumes"],"answer_index":1,"explanation":"Gay-Lussac’s ratio for $2\\mathrm{H_2} + \\mathrm{O_2} \\rightarrow 2\\mathrm{H_2O(g)}$ is 2 : 1 : 2 by volume.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"laws-combination","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-110","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Two oxides of copper are analysed. In the first, 6.35 g of copper is combined with 0.80 g of oxygen; in the second, 6.35 g of copper is combined with 1.60 g of oxygen. The oxygen masses that combine with the same mass of copper are in the ratio","options":["1 : 2","2 : 3","3 : 4","4 : 5"],"answer_index":0,"explanation":"Fixed 6.35 g Cu takes 0.80 g then 1.60 g of oxygen, a 1 : 2 ratio, which is Dalton’s multiple-proportion test.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"laws-combination","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-111","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Avogadro’s constant $N_A$ is accepted as approximately","options":["$6.022 \\times 10^{23}\\ \\mathrm{mol^{-1}}$","$6.022 \\times 10^{22}\\ \\mathrm{mol^{-1}}$","$3.011 \\times 10^{23}\\ \\mathrm{mol^{-1}}$","$1.602 \\times 10^{-19}\\ \\mathrm{mol^{-1}}$"],"answer_index":0,"explanation":"One mole contains $6.022 \\times 10^{23}$ specified elementary entities.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-112","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The SI mole is defined so that 12 g of the carbon-12 nuclide contains","options":["one atom of carbon-12","$6.022 \\times 10^{23}$ carbon-12 atoms","12 carbon-12 atoms","$12 \\times 6.022 \\times 10^{23}$ atoms"],"answer_index":1,"explanation":"By definition, 12 g of $^{12}\\mathrm{C}$ is 1 mol and therefore holds $N_A$ atoms.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-113","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The amount of substance $n$ and the number of elementary entities $N$ are linked by","options":["$n = N \\times N_A$","$n = N / N_A$","$n = N_A / N$","$n = N + N_A$"],"answer_index":1,"explanation":"Dividing the particle count by Avogadro’s constant converts it to moles.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-114","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"One unified atomic mass unit (1 u) is defined as","options":["the mass of one hydrogen atom","one-twelfth of the mass of a carbon-12 atom","the mass of one oxygen-16 atom","1 g exactly"],"answer_index":1,"explanation":"The u (or amu) is $1/12$ of the mass of a single $^{12}\\mathrm{C}$ atom.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-115","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Gram-atomic mass of an element is the mass, in grams, of","options":["one atom of the element","one mole of its atoms","one molecule only","Avogadro’s number of molecules of any compound"],"answer_index":1,"explanation":"The gram-atomic mass is numerically equal to the atomic mass and is the mass of $N_A$ atoms.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-116","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"At 273 K and 1 atm (classic STP), the molar volume of an ideal gas is taken in Intermediate tables as","options":["11.2 L","22.4 L","24.0 L","44.8 L"],"answer_index":1,"explanation":"One mole of ideal gas occupies 22.4 L at 273 K and 1 atm.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-117","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A pair of samples that must contain the same number of molecules is","options":["1 mol of $\\mathrm{O_2}$ and 1 mol of $\\mathrm{O_3}$","16 g of $\\mathrm{O_2}$ and 16 g of $\\mathrm{O_3}$","1 mol of $\\mathrm{O_2}$ and 2 mol of $\\mathrm{He}$","22.4 L of $\\mathrm{H_2}$ at STP and 11.2 L of $\\mathrm{He}$ at STP"],"answer_index":0,"explanation":"Equal amounts in moles contain equal numbers of molecules, whatever the formula.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-118","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Half a mole of dioxygen molecules contains oxygen atoms numbering","options":["$0.5\\,N_A$","$N_A$","$2\\,N_A$","$0.25\\,N_A$"],"answer_index":1,"explanation":"Each $\\mathrm{O_2}$ molecule has two atoms, so $0.5\\,N_A$ molecules hold $N_A$ atoms.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-119","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The numerical value $1.66 \\times 10^{-24}$ g is the approximate mass of","options":["one mole of protons","one unified atomic mass unit","one electron","one mole of $^{12}\\mathrm{C}$"],"answer_index":1,"explanation":"1 u $\\approx 1.66 \\times 10^{-24}$ g, which is $1/N_A$ grams.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-120","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Twelve grams of carbon-12 and eighteen grams of water both represent","options":["the same number of atoms","one mole of the stated substance","two moles of molecules","half a mole of each"],"answer_index":1,"explanation":"12 g of $^{12}\\mathrm{C}$ is 1 mol of atoms; 18 g of $\\mathrm{H_2O}$ is 1 mol of molecules.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-121","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"If a flask holds $3.011 \\times 10^{23}$ molecules of nitrogen, the amount of $\\mathrm{N_2}$ in that flask is","options":["0.25 mol","0.50 mol","1.00 mol","2.00 mol"],"answer_index":1,"explanation":"$N / N_A = 3.011 \\times 10^{23} / 6.022 \\times 10^{23} = 0.50$ mol.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-122","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"One mole of helium atoms and one mole of hydrogen molecules agree in","options":["total mass","number of elementary entities counted as ‘one mole’","number of atoms","density at STP"],"answer_index":1,"explanation":"A mole always contains $N_A$ of the named entities: He atoms or $\\mathrm{H_2}$ molecules.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-123","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"An STP sample of ammonia occupying 11.2 L contains molecules numbering","options":["$6.022 \\times 10^{23}$","$3.011 \\times 10^{23}$","$1.505 \\times 10^{23}$","$12.044 \\times 10^{23}$"],"answer_index":1,"explanation":"11.2 L at STP is 0.50 mol, so the molecule count is $0.50\\,N_A = 3.011 \\times 10^{23}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-124","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A 4.4 g portion of carbon dioxide is analysed for atoms. Taking $M(\\mathrm{CO_2}) = 44\\ \\mathrm{g\\,mol^{-1}}$, the total number of atoms present is","options":["$0.1\\,N_A$","$0.3\\,N_A$","$N_A$","$3\\,N_A$"],"answer_index":1,"explanation":"4.4 g is 0.10 mol of $\\mathrm{CO_2}$; each molecule has 3 atoms, giving $0.30\\,N_A$ atoms.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-125","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Compare 16 g of methane with 16 g of dioxygen. The sample that holds more molecules is","options":["the methane sample","the dioxygen sample","neither; the molecule counts are equal","impossible to decide without density"],"answer_index":0,"explanation":"16 g $\\mathrm{CH_4}$ is 1.0 mol of molecules; 16 g $\\mathrm{O_2}$ is only 0.50 mol, so methane has twice as many molecules.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
    id text,
    chapter_id text,
    subject_id text,
    stem text,
    options jsonb,
    answer_index int,
    explanation text,
    images jsonb,
    source jsonb,
    difficulty text,
    concept_id text,
    appear_count int,
    years jsonb,
    exams jsonb,
    verified boolean
  )
on conflict (question_id) do update set
  appear_count = excluded.appear_count,
  years = excluded.years,
  exams = excluded.exams,
  verified = excluded.verified;